<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $group = $args['group']; ?><section id="members" class="sd-panel"><h2><?php esc_html_e( 'Members', 'social-discovery' ); ?></h2><?php if ( function_exists( 'groups_get_group_members' ) ) : $members = groups_get_group_members( array( 'group_id' => $group->id, 'per_page' => 6, 'page' => 1 ) ); if ( ! empty( $members['members'] ) ) : ?><ul class="sd-group-member-list"><?php foreach ( $members['members'] as $member ) : ?><li><a href="<?php echo esc_url( sd_get_member_url( $member->user_id ) ); ?>"><?php echo wp_kses_post( sd_avatar( $member->user_id, 40 ) ? '<img src="' . esc_url( sd_avatar( $member->user_id, 40 ) ) . '" alt="">' : '' ); ?><span><?php echo esc_html( function_exists( 'bp_core_get_user_displayname' ) ? bp_core_get_user_displayname( $member->user_id ) : __( 'Member', 'social-discovery' ) ); ?></span></a></li><?php endforeach; ?></ul><?php else : ?><p class="sd-muted"><?php esc_html_e( 'No members to display.', 'social-discovery' ); ?></p><?php endif; else : ?><p class="sd-muted"><?php esc_html_e( 'Member lists are available when BuddyPress Groups is active.', 'social-discovery' ); ?></p><?php endif; ?></section>
